    adcs_vec3_t u, v;
    double c, s_norm;
    adcs_vec3_t cross_uv;

    if ((primary == NULL) || (secondary == NULL) || 
        (separation_rad == NULL) || (cross_sine == NULL) || 
        (condition_proxy == NULL)) {
        return ADCS_E_NULL;
    }

    if (adcs_vec3_normalize(primary, ADCS_EPS_NORM, &u) != ADCS_OK) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    if (adcs_vec3_normalize(secondary, ADCS_EPS_NORM, &v) != ADCS_OK) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    c = adcs_vec3_dot(&u, &v);
    cross_uv = adcs_vec3_cross(&u, &v);
    s_norm = adcs_vec3_norm(&cross_uv);

    if (s_norm <= ADCS_EPS_COLLINEAR) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    *separation_rad = atan2(s_norm, c);
    *cross_sine = s_norm;
    *condition_proxy = 1.0 / s_norm;

    return ADCS_OK;
}

