    if ((primary == NULL) || (secondary == NULL) || 
        (separation_rad == NULL) || (cross_sine == NULL) || 
        (condition_proxy == NULL)) {
        return ADCS_E_NULL;
    }

    *separation_rad = 0.0;
    *cross_sine = 0.0;
    *condition_proxy = INFINITY;

    if (!adcs_is_finite_vec3(primary) || !adcs_is_finite_vec3(secondary)) {
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t u, v;
    if (adcs_vec3_normalize(primary, ADCS_EPS_NORM, &u) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    if (adcs_vec3_normalize(secondary, ADCS_EPS_NORM, &v) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    double c = adcs_vec3_dot(&u, &v);
    c = ADCS_CLAMP(c, -1.0, 1.0);

    adcs_vec3_t cross_v = adcs_vec3_cross(&u, &v);
    double s = adcs_vec3_norm(&cross_v);

    if (s <= ADCS_EPS_COLLINEAR) {
        return ADCS_E_DEGENERATE;
    }

    *separation_rad = atan2(s, c);
    *cross_sine = s;
    *condition_proxy = 1.0 / s;

    return ADCS_OK;
}

